<?php
require __DIR__.'/../database/runtime.php';
 $user=requireUser();
if(($_GET['action']??'')==='messages'){
  ensureMessagingSchema();
  $canMessage=function(int $fromId,int $toId,int $requestedEvent=0)use($pdo,$user):array|false{
    if($fromId===$toId)return false;$q=$pdo->prepare('SELECT id,role,email FROM users WHERE id=?');$q->execute([$toId]);$to=$q->fetch();if(!$to)return false;
    if($user['role']==='admin')return $to['role']==='organizer'?['eventId'=>null,'contact'=>$to]:false;
    if($to['role']==='admin'&&in_array($user['role'],['organizer','user'],true))return ['eventId'=>null,'contact'=>$to];
    if($user['role']==='organizer'&&$to['role']==='user'){$sql='SELECT e.id FROM bookings b JOIN events e ON e.id=b.event_id WHERE e.organizer_id=? AND b.user_email=?'.($requestedEvent?' AND e.id=?':'').' ORDER BY e.event_date DESC LIMIT 1';$args=[$fromId,$to['email']];if($requestedEvent)$args[]=$requestedEvent;$q=$pdo->prepare($sql);$q->execute($args);$event=$q->fetchColumn();return $event?['eventId'=>(int)$event,'contact'=>$to]:false;}
    if($user['role']==='user'&&$to['role']==='organizer'){$sql='SELECT e.id FROM bookings b JOIN events e ON e.id=b.event_id WHERE b.user_email=? AND e.organizer_id=?'.($requestedEvent?' AND e.id=?':'').' ORDER BY e.event_date DESC LIMIT 1';$args=[$user['email'],$to['id']];if($requestedEvent)$args[]=$requestedEvent;$q=$pdo->prepare($sql);$q->execute($args);$event=$q->fetchColumn();return $event?['eventId'=>(int)$event,'contact'=>$to]:false;}
    return false;
  };
  if($_SERVER['REQUEST_METHOD']==='GET'){
    if($user['role']==='admin')$contacts=$pdo->query("SELECT id,first_name,last_name,email,role FROM users WHERE role='organizer' ORDER BY first_name,last_name")->fetchAll();
    elseif($user['role']==='organizer'){$q=$pdo->prepare("SELECT DISTINCT u.id,u.first_name,u.last_name,u.email,u.role FROM users u JOIN bookings b ON b.user_email=u.email JOIN events e ON e.id=b.event_id WHERE e.organizer_id=? AND u.role='user' ORDER BY u.first_name,u.last_name");$q->execute([$user['id']]);$contacts=$q->fetchAll();}
    elseif($user['role']==='user'){$q=$pdo->prepare("SELECT DISTINCT u.id,u.first_name,u.last_name,u.email,u.role FROM users u JOIN events e ON e.organizer_id=u.id JOIN bookings b ON b.event_id=e.id WHERE b.user_email=? AND u.role='organizer' ORDER BY u.first_name,u.last_name");$q->execute([$user['email']]);$contacts=$q->fetchAll();}
    else reply(['error'=>'La messagerie est réservée aux comptes organisateurs, clients et administrateurs.'],403);
    $q=$pdo->prepare("SELECT id,first_name,last_name,email,role FROM users WHERE role='admin' ORDER BY id LIMIT 1");$q->execute();$adminContact=$q->fetch();if($adminContact&&$user['role']!=='admin')$contacts[]=$adminContact;
    foreach($contacts as &$contact){$q=$pdo->prepare('SELECT COUNT(*) FROM messages WHERE sender_id=? AND recipient_id=? AND read_at IS NULL');$q->execute([$contact['id'],$user['id']]);$contact['unread']=(int)$q->fetchColumn();}unset($contact);
    $messages=[];$contactId=(int)($_GET['contact']??0);if($contactId){$relation=$canMessage((int)$user['id'],$contactId,(int)($_GET['eventId']??0));if(!$relation)reply(['error'=>'Cette conversation n’est pas autorisée.'],403);$q=$pdo->prepare('SELECT m.id,m.sender_id,m.recipient_id,m.related_event_id,m.body,m.created_at,m.read_at,e.title AS event_title FROM messages m LEFT JOIN events e ON e.id=m.related_event_id WHERE (m.sender_id=? AND m.recipient_id=?) OR (m.sender_id=? AND m.recipient_id=?) ORDER BY m.id DESC LIMIT 200');$q->execute([$user['id'],$contactId,$contactId,$user['id']]);$messages=array_reverse($q->fetchAll());$pdo->prepare('UPDATE messages SET read_at=NOW() WHERE sender_id=? AND recipient_id=? AND read_at IS NULL')->execute([$contactId,$user['id']]);}
    reply(['contacts'=>$contacts,'messages'=>$messages,'userId'=>(int)$user['id']]);
  }
  if($_SERVER['REQUEST_METHOD']==='POST'){$d=body();rateLimit('message-send:'.$user['id'],30,60);$toId=(int)($d['recipientId']??0);$eventId=(int)($d['eventId']??0);$message=trim((string)($d['message']??''));$length=function_exists('mb_strlen')?mb_strlen($message,'UTF-8'):strlen($message);if($message===''||$length>3000)reply(['error'=>'Le message doit contenir entre 1 et 3 000 caractères.'],422);$relation=$canMessage((int)$user['id'],$toId,$eventId);if(!$relation)reply(['error'=>'Vous pouvez écrire uniquement à l’administrateur, à un client ayant réservé l’un de vos événements ou à son organisateur.'],403);$pdo->prepare('INSERT INTO messages(sender_id,recipient_id,related_event_id,body) VALUES(?,?,?,?)')->execute([$user['id'],$toId,$relation['eventId'],$message]);$id=(string)$pdo->lastInsertId();$pdo->prepare('INSERT INTO audit_log(actor_email,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)')->execute([$user['email'],'message.sent','message',$id,json_encode(['recipient_id'=>$toId,'event_id'=>$relation['eventId']])]);reply(['sent'=>true,'id'=>$id]);}
  reply(['error'=>'Méthode invalide.'],405);
}
if(!in_array($user['role'],['admin','organizer'],true))reply(['error'=>'Un compte organisateur ou administrateur est nécessaire.'],403);
expirePendingBookings();
$scope=$user['role']==='admin'?'':' WHERE organizer_id=?';
$args=$user['role']==='admin'?[]:[$user['id']];
$eventCount=$pdo->prepare('SELECT COUNT(*) FROM events'.$scope);$eventCount->execute($args);
$soldQ=$pdo->prepare('SELECT COALESCE(SUM(e.capacity-e.available_tickets),0) FROM events e'.($scope?' WHERE e.organizer_id=?':''));$soldQ->execute($args);
$revenueQ=$pdo->prepare("SELECT COALESCE(SUM(b.total),0) FROM bookings b JOIN events e ON e.id=b.event_id WHERE b.status='confirmed'".($scope?' AND e.organizer_id=?':''));$revenueQ->execute($args);
$stats=['events'=>(int)$eventCount->fetchColumn(),'sold'=>(int)$soldQ->fetchColumn(),'revenue'=>(float)$revenueQ->fetchColumn()];
$dailySql="SELECT DATE(b.created_at) AS day,COUNT(*) AS orders,COALESCE(SUM(b.total),0) AS revenue FROM bookings b JOIN events e ON e.id=b.event_id WHERE b.status='confirmed' AND b.created_at>=DATE_SUB(CURDATE(),INTERVAL 13 DAY)".($scope?' AND e.organizer_id=?':'').' GROUP BY DATE(b.created_at) ORDER BY day';$dailyQ=$pdo->prepare($dailySql);$dailyQ->execute($args);$dailyRows=[];foreach($dailyQ->fetchAll() as $row)$dailyRows[$row['day']]=['day'=>$row['day'],'orders'=>(int)$row['orders'],'revenue'=>(float)$row['revenue']];$salesTrend=[];for($i=13;$i>=0;$i--){$day=date('Y-m-d',strtotime('-'.$i.' days'));$salesTrend[]=$dailyRows[$day]??['day'=>$day,'orders'=>0,'revenue'=>0.0];}
$eventSql='SELECT id,title,event_date AS date,location,price,capacity,available_tickets AS availableTickets,category,status,visibility FROM events'.($scope?' WHERE organizer_id=?':'').' ORDER BY event_date LIMIT 8';$eventsQ=$pdo->prepare($eventSql);$eventsQ->execute($args);$events=$eventsQ->fetchAll();
foreach($events as &$e){$e['id']=(string)$e['id'];$e['capacity']=(int)$e['capacity'];$e['availableTickets']=(int)$e['availableTickets'];$e['price']=(float)$e['price'];}unset($e);
$where=$scope?' AND e.organizer_id=?':'';
foreach(['attendees'=>"SELECT COUNT(DISTINCT b.user_email) FROM bookings b JOIN events e ON e.id=b.event_id WHERE b.status='confirmed'",'reservations'=>'SELECT COUNT(*) FROM bookings b JOIN events e ON e.id=b.event_id WHERE 1=1','pending'=>"SELECT COUNT(*) FROM bookings b JOIN events e ON e.id=b.event_id WHERE b.status='pending_payment'",'checkedIn'=>'SELECT COUNT(*) FROM issued_tickets t JOIN events e ON e.id=t.event_id WHERE t.scanned_at IS NOT NULL'] as $key=>$sql){$q=$pdo->prepare($sql.$where);$q->execute($args);$stats[$key]=(int)$q->fetchColumn();}
$activitySql='SELECT actor_email AS actor,action,entity_type,entity_id,created_at FROM audit_log'.($scope?' WHERE (entity_type=\'event\' AND entity_id IN (SELECT CAST(id AS CHAR) FROM events WHERE organizer_id=?)) OR (entity_type=\'booking\' AND entity_id IN (SELECT CAST(b.id AS CHAR) FROM bookings b JOIN events e ON e.id=b.event_id WHERE e.organizer_id=?)) OR (entity_type=\'ticket\' AND entity_id IN (SELECT t.id FROM issued_tickets t JOIN events e ON e.id=t.event_id WHERE e.organizer_id=?))':'').' ORDER BY id DESC LIMIT 8';$activityQ=$pdo->prepare($activitySql);$activityQ->execute($scope?[$user['id'],$user['id'],$user['id']]:[]);$activity=$activityQ->fetchAll();
$requests=[];if($user['role']==='admin')$requests=$pdo->query("SELECT r.id,r.organization_name,r.phone,r.status,r.created_at,u.first_name,u.last_name,u.email FROM organizer_requests r JOIN users u ON u.id=r.user_id WHERE r.status='pending' ORDER BY r.created_at")->fetchAll();
reply(['stats'=>$stats,'events'=>$events,'activity'=>$activity,'salesTrend'=>$salesTrend,'organizerRequests'=>$requests,'role'=>$user['role']]);
